// Construtores das linhas tipadas, compartilhados por todos os plugins.
export const h = (text, meta) => ({ t: 'h', text, meta });
export const row = (id, g, text, meta, tone, extra) => ({ t: 'row', id, g, text, meta, tone, ...extra });
