const get = (o, path) => String(path).split('.').reduce((x, k) => x?.[k], o);
const STOP = new Set(['', undefined, null]);

// ${campo} · ${campo?sim:não} · ${$args}
export function fill(tpl, item = {}, args = '') {
  if (typeof tpl !== 'string') return tpl;
  return tpl.replace(/\$\{([^}]+)\}/g, (_, e) => {
    if (e === '$args') return args;
    const q = e.indexOf('?');
    if (q > 0) { const [yes, no = ''] = e.slice(q + 1).split(':'); return get(item, e.slice(0, q)) ? yes : no; }
    const v = get(item, e);
    return Array.isArray(v) ? v.join(' ') : v ?? '';
  });
}
const deep = (v, item, args) => typeof v === 'string' ? fill(v, item, args) : Array.isArray(v) ? v.map(x => deep(x, item, args)) : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, deep(x, item, args)])) : v;

export const seed = () => structuredClone(Object.assign({}, ...Object.values(MANIFESTS).map(m => m.seed ?? {})));
export const viewsOf = (plugin, leaf) => (leaf?.data.mode === 'detail' && MANIFESTS[plugin]?.detailViews) || MANIFESTS[plugin]?.views || [];
