const manifest = leaf => MANIFESTS[leaf.plugin];
const currentView = leaf => viewsOf(leaf.plugin, leaf).find(v => v.id === leaf.data.view);

function matches(x, where, leaf) {
  if (!where) return true;
  if (typeof where === 'string') return where.startsWith('!') ? !x[where.slice(1)] : !!x[where];
  return Object.entries(where).every(([k, v]) => typeof v === 'string' && v.startsWith('data.') ? [].concat(x[k]).includes(get(leaf.data, v.slice(5))) || STOP.has(get(leaf.data, v.slice(5))) : x[k] === v);
}

export const findItem = (S, list, id) => (S.store[MANIFESTS_LIST[list]?.store ?? list] ?? []).find(x => x.id === id);
const MANIFESTS_LIST = Object.assign({}, ...Object.values(MANIFESTS).map(m => m.lists ?? {}));

export function listLines(S, leaf, view, count = { shown: 0, total: 0 }) {
  const list = MANIFESTS_LIST[view.list], row = list.row;
  let xs = (S.store[list.store] ?? []).filter(x => matches(x, view.where, leaf) && matches(x, view.sub ? view.sub[leaf.data.sub ?? 0]?.where : null, leaf));
  const raw = !leaf.data.editing && !leaf.input.text.startsWith('/') ? leaf.input.text : '', q = raw.toLowerCase();
  count.total += xs.length;
  if (q) xs = xs.filter(x => `${fill(row.text, x)} ${fill(row.meta, x)}`.toLowerCase().includes(q));
  count.shown += xs.length;
  const sort = list.sorts?.[leaf.data.sort ?? list.sort];
  if (sort) xs = [...xs].sort((a, b) => sort[0] === '!' ? (b[sort.slice(1)] ? 1 : 0) - (a[sort.slice(1)] ? 1 : 0) : sort[0] === '-' ? b[sort.slice(1)] - a[sort.slice(1)] : String(a[sort]).localeCompare(String(b[sort])));
  const lines = [];
  let group;
  for (const x of xs) {
    if (view.group && x[view.group] !== group) lines.push({ t: 'h', text: String(group = x[view.group]) });
    lines.push({ t: 'row', id: `${view.list}:${x.id}`, ref: { list: view.list, id: x.id }, g: fill(row.g ?? '·', x), text: fill(row.text, x), meta: fill(row.meta ?? '', x), tone: fill(row.tone ?? '', x) || null });
  }
  if (!lines.length && !view.quiet) lines.push({ t: 'note', text: q ? `nada com “${raw}” · ${CREATES[leaf.plugin] ? '↵ cria' : '↵ busca em tudo'}` : view.empty ?? 'nada aqui', tone: 'dim' });
  return lines;
}

const show = (v, f, item) => f.type === 'member' ? ((item[f.field] ?? []).includes(f.value) ? 'sim' : 'não') : f.type === 'display' ? fill(f.value ?? '', item) : f.type === 'bool' ? (v ? 'sim' : 'não') : Array.isArray(v) ? v.join(', ') || '—' : STOP.has(v) ? '—' : String(v).split('\n')[0] + (String(v).includes('\n') ? ' …' : '');
export function fichaLines(S, leaf) {
  const f = leaf.data.form, m = manifest(leaf), item = findItem(S, f.list, f.id);
  if (!item) return [{ t: 'note', text: 'item removido', tone: 'dim' }];
  return [{ t: 'h', text: `${f.label ?? f.name} · ${fill(MANIFESTS_LIST[f.list].row.text, item) || 'novo'}`, meta: 'esc volta' },
    ...m.forms[f.name].map(x => ({ t: 'row', id: `f:${x.field}`, field: x, g: x.type === 'bool' ? (item[x.field] ? '●' : '○') : x.type === 'member' ? ((item[x.field] ?? []).includes(x.value) ? '●' : '○') : '·', text: x.label, meta: show(item[x.field], x, item) }))];
}

export function engineView(leaf, S) {
  if (leaf.data.view === 'ficha' && leaf.data.form) return { lines: fichaLines(S, leaf) };
  const v = currentView(leaf);
  if (!v?.list && !v?.blocks) return null;
  const status = [v.status && (!v.statusIf || leaf.data[v.statusIf]) && fill(v.status, leaf.data), v.sub && `← ${v.sub[leaf.data.sub ?? 0].label} →`, leaf.data.sort && `ordem: ${leaf.data.sort}`].filter(Boolean).join(' · ');
  // Vista com blocos: várias listas em sequência, cada uma com seu cabeçalho (ex.: contas + opções).
  const count = { shown: 0, total: 0 }, q = !leaf.data.editing && !leaf.input.text.startsWith('/') && leaf.input.text;
  let lines = v.blocks ? v.blocks.flatMap(b => { const ls = listLines(S, leaf, { ...b, quiet: !!q }, count); return ls.length ? [{ t: 'h', text: b.label }, ...ls] : []; }) : listLines(S, leaf, v, count);
  if (!lines.length) lines = listLines(S, leaf, { ...v.blocks[0], empty: v.empty }, { shown: 0, total: 0 });
  return { lines, status: [q && `${count.shown} de ${count.total}`, status].filter(Boolean).join(' · ') || undefined };
}

export function actionsFor(leaf, item, S) {
  if (item?.ref) return (MANIFESTS_LIST[item.ref.list].actions ?? []).filter(a => !a.when || matches(findItem(S, item.ref.list, item.ref.id) ?? {}, a.when, leaf));
  return manifest(leaf)?.itemActions?.[item?.kind] ?? [];
}

// Executa uma operação sobre o rascunho do estado. Devolve um efeito para o modelo (log, overlay, actions, cursor, input).
export function runOp(S, leaf, op, ctx = {}) {
  if (!op) return false;
  const item = ctx.item ?? (ctx.list && findItem(S, ctx.list, ctx.id));
  const T = v => deep(v, { ...item, data: leaf.data }, ctx.args ?? '');
  const base = root => ({ item, data: leaf.data, store: S.store, ui: S.ui, ctx: leaf.ctx })[root];
  const split = p => { const [root, ...rest] = p.split('.'); return [base(root), rest]; };
  const read = p => { const [b, rest] = split(p); return rest.reduce((x, k) => x?.[k], b); };
  const put = (p, v) => { const [b, rest] = split(p); let o = b; for (const k of rest.slice(0, -1)) o = o[k] ??= {}; o[rest.at(-1)] = v; };
  const store = () => S.store[MANIFESTS_LIST[ctx.list]?.store];
  switch (op.op) {
    case 'set':
      if (op.exclusive) for (const x of store()) x[op.path.slice(5)] = false;
      put(op.path, T(op.value)); return { toast: op.toast && T(op.toast) };
    case 'toggle': put(op.path, !read(op.path)); return { toast: op.toast && T(op.toast) };
    case 'cycle': { const vs = op.values; put(op.path, vs[(vs.indexOf(read(op.path)) + 1) % vs.length]); return { toast: op.toast && T(op.toast) }; }
    case 'view': leaf.data.view = op.view; return { cursor: 0 };
    case 'edit': {
      leaf.data.editing = op.path ? { path: op.path, label: op.label } : { list: ctx.list, id: item.id, field: op.field, label: op.label ?? op.field };
      const v = op.path ? read(op.path) : item[op.field];
      return { input: Array.isArray(v) ? v.join(', ') : String(v ?? '') };
    }
    case 'new': case 'form': {
      const list = op.list ?? ctx.list;
      let target = item;
      if (op.op === 'new') {
        target = { id: `${list}.${S.seq++}`, ...T(op.item ?? {}) };
        (S.store[MANIFESTS_LIST[list].store] ??= []).push(target);
      }
      if (!op.form) return { toast: op.toast && T(op.toast) };
      leaf.data.form = { name: op.form, label: op.label, list, id: target.id, back: op.back ?? leaf.data.view };
      leaf.data.view = 'ficha';
      return { cursor: 0 };
    }
    case 'remove':
      if (op.confirm && !ctx.confirmed) return { overlay: { kind: 'confirm', text: T(op.confirm), action: { type: 'OP', pane: leaf.id, op, list: ctx.list, id: item.id, item: ctx.list ? undefined : item, confirmed: true } } };
      S.store[MANIFESTS_LIST[ctx.list].store] = store().filter(x => x !== item);
      return { toast: T(op.toast ?? 'removido') };
    case 'dup': store().push({ ...structuredClone(item), id: `${ctx.list}.${S.seq++}`, [op.field ?? 'name']: `${item[op.field ?? 'name']} (cópia)` }); return { toast: 'cópia criada' };
    case 'push': { const v = { id: `i${S.seq++}`, ...T(op.value) }; put(op.path, [...(read(op.path) ?? []), op.raw ? T(op.value) : v]); return { toast: op.toast && T(op.toast) }; }
    case 'log': return { log: { cmd: T(op.cmd), out: T(op.out ?? []), ok: op.ok ?? true, g: op.g } };
    case 'toast': S.ui.toast = T(op.text); return {};
    case 'goto': return { actions: [{ type: op.beside ? 'CHAT_BESIDE' : 'GOTO', plugin: T(op.plugin) }, ...(op.input ? [{ type: 'SET_INPUT', text: T(op.input) }] : [])] };
    case 'confirm':
      if (ctx.confirmed) return runOp(S, leaf, op.then, { ...ctx, confirmed: false });
      return { overlay: { kind: 'confirm', text: T(op.text), action: { type: 'OP', pane: leaf.id, op, list: ctx.list, id: item?.id, item: ctx.list ? undefined : item, args: ctx.args, confirmed: true } } };
    case 'async': leaf.data.busy = { label: T(op.label), then: op.then, list: ctx.list, id: item?.id, args: ctx.args }; return {};
    case 'seq': return op.ops.reduce((fx, o) => merge(fx, runOp(S, leaf, o, ctx)), {});
    case 'fn': return FN[op.name]?.(S, leaf, { ...ctx, item }, op) ?? false;
    case 'act': return runOp(S, leaf, MANIFESTS_LIST[ctx.list]?.actions?.find(a => a.key === op.key)?.op, ctx);
    default: return false;
  }
}
const merge = (a, b) => !b ? a : { ...a, ...b, actions: [...(a.actions ?? []), ...(b.actions ?? [])], log: b.log ?? a.log };

export function commitEdit(S, leaf, text) {
  const e = leaf.data.editing;
  leaf.data.editing = null;
  if (e.path) { runOp(S, leaf, { op: 'set', path: e.path, value: text }); return e.then ? runOp(S, leaf, e.then, {}) : true; }
  const item = findItem(S, e.list, e.id);
  if (!item) return false;
  const field = manifest(leaf)?.forms?.[leaf.data.form?.name]?.find(f => f.field === e.field);
  item[e.field] = field?.type === 'list' ? text.split(',').map(s => s.trim()).filter(Boolean) : text;
  return { toast: `${e.label}: ${text.length > 40 ? `${text.slice(0, 40)}…` : text || '—'}` };
}

// ↵ e espaço no motor: ficha edita/alterna; lista executa a operação declarada.
export function engineKey(S, leaf, key, line) {
  if (!line) return null;
  if (line.field) {
    const f = line.field, form = leaf.data.form, item = findItem(S, form.list, form.id);
    if (f.type === 'bool') return runOp(S, leaf, { op: 'toggle', path: `item.${f.field}` }, { item });
    if (f.type === 'member') { const xs = item[f.field] ?? []; item[f.field] = xs.includes(f.value) ? xs.filter(x => x !== f.value) : [...xs, f.value]; return {}; }
    if (f.type === 'choice') return runOp(S, leaf, { op: 'cycle', path: `item.${f.field}`, values: f.values }, { item });
    if (key === ' ' || f.type === 'display') return null;
    return runOp(S, leaf, { op: 'edit', field: f.field, label: f.label }, { item, list: form.list });
  }
  if (!line.ref) return null;
  const list = MANIFESTS_LIST[line.ref.list], op = key === ' ' ? list.space : list.enter;
  return op ? runOp(S, leaf, op, { list: line.ref.list, id: line.ref.id }) : null;
}

// Plugin descrito por manifesto: vistas, listas, fichas e comandos vêm dos dados; o código só cobre o que é próprio.
export function fromManifest(base) {
  const m = MANIFESTS[base.id] ?? {};
  CREATES[base.id] = !!(m.submit || base.submit);
  return {
    ...base,
    init: leaf => ({ ...(base.init?.(leaf) ?? {}) }),
    view: (leaf, S) => engineView(leaf, S) ?? base.view?.(leaf, S) ?? { lines: [] },
    keys: (leaf, S) => [' ', ...(base.keys?.(leaf, S) ?? [])],
    key: (leaf, key, item, S) => (key === ' ' && engineKey(S, leaf, ' ', item)) || base.key?.(leaf, key, item, S) || null,
    activate: (leaf, item, S) => engineKey(S, leaf, '↵', item) || base.activate?.(leaf, item, S) || null,
    submit: (leaf, text, S) => m.submit ? runOp(S, leaf, m.submit, { args: text }) : base.submit?.(leaf, text, S),
    commands: [...(m.commands ?? []).map(c => ({ name: c.name, desc: c.desc, run: (leaf, args, S) => runOp(S, leaf, c.op, { args }) })), ...(base.commands ?? [])],
  };
}

